export function resolveExerciseImageSource(
  imageUri?: string | null,
): ImageSourcePropType {
  if (!imageUri) {
    return EXERCISE_PLACEHOLDER_IMAGE;
  }

  const bundledSource = EXERCISE_MEDIA_ASSET_MAP[imageUri];
  if (bundledSource) {
    return bundledSource;
  }

  if (imageUri.startsWith('assets/images/exercises/')) {
    return EXERCISE_PLACEHOLDER_IMAGE;
  }

  return { uri: imageUri };
}

export { EXERCISE_PLACEHOLDER_IMAGE };
